<?php
// Mullion Watch — the watcher itself, loaded by mullion-watch.php for a
// watched site only. Generated by mullion: do not edit, changes are
// overwritten.
//
// How it hooks Laravel without any change to the project:
//   1. It loads the project's Composer autoloader early (vendor/autoload.php
//      is safe to require twice: the second require returns the same
//      loader) and puts its own autoloader in FRONT of Composer's.
//   2. That autoloader only watches class names: the first time one of
//      Illuminate\Foundation\Bootstrap\* is asked for, the Application
//      exists (it is the container instance) — the watcher then calls
//      $app->booted(...) and its autoloader becomes a no-op.
//   3. Once the app has booted, it registers event listeners (queries,
//      cache, jobs, HTTP client, views, logs, mail, app events) and its
//      dump() handler (after Laravel's own, which it keeps for "show in
//      page too").
// Everything is buffered in memory and appended to <dir>/events.jsonl
// once, at the end of the request (per job for queue workers), under
// flock. Every hook is wrapped so a failure here never reaches the app.

namespace MullionWatch;

final class Watcher
{
    const CAP = 20971520;      // rotate events.jsonl past 20 MB (keeps one events.1.jsonl)
    const MAX_EVENTS = 3000;   // per request / job
    const MAX_STR = 2000;

    private static $dir;
    private static $cfg;
    private static $rid;
    private static $baseRid;
    private static $start;
    private static $buf = [];
    private static $dropped = 0;
    private static $count = 0;
    private static $cli;
    private static $hooked = false;
    private static $loaderFn;
    private static $base = '';
    private static $prevDumper;
    private static $route = null;
    private static $httpStart = [];
    private static $jobStart = 0.0;
    private static $inside = false;
    private static $status = null;

    public static function start($dir, array $cfg)
    {
        self::$dir = $dir;
        self::$cfg = $cfg;
        self::$cli = PHP_SAPI === 'cli' || PHP_SAPI === 'phpdbg';
        self::$start = isset($_SERVER['REQUEST_TIME_FLOAT']) ? (float) $_SERVER['REQUEST_TIME_FLOAT'] : microtime(true);
        $rid = $_SERVER['MULLION_RID'] ?? '';
        if (!is_string($rid) || $rid === '' || strpos($rid, '{') !== false) {
            $rid = (self::$cli ? 'cli-' : 'req-') . bin2hex(random_bytes(6));
        }
        self::$rid = self::$baseRid = $rid;

        register_shutdown_function([self::class, 'shutdown']);

        $autoload = self::findAutoload();
        if ($autoload === null) {
            return;
        }
        self::$base = dirname(dirname($autoload));
        require $autoload;

        // In front of Composer's: see the header comment.
        self::$loaderFn = static function ($class) {
            if (!self::$hooked && strncmp($class, 'Illuminate\\Foundation\\Bootstrap\\', 32) === 0) {
                self::tryHook();
            }
        };
        spl_autoload_register(self::$loaderFn, true, true);

        // Not Laravel (or before it boots): dumps still go to Mullion.
        if (!empty($cfg['dumps'])) {
            self::guard(static function () {
                if (class_exists('Symfony\\Component\\VarDumper\\VarDumper')) {
                    self::installDumper();
                }
            });
        }
    }

    private static function findAutoload()
    {
        $dirs = [];
        if (self::$cli) {
            $argv = $_SERVER['argv'] ?? [];
            if (isset($argv[0])) {
                $dirs[] = dirname((string) (realpath($argv[0]) ?: $argv[0]));
            }
            $dirs[] = getcwd();
        } else {
            $script = $_SERVER['SCRIPT_FILENAME'] ?? '';
            if ($script !== '') {
                $d = dirname($script);
                for ($i = 0; $i < 3; $i++) {
                    $dirs[] = $d;
                    $d = dirname($d);
                }
            }
            if (!empty($_SERVER['DOCUMENT_ROOT'])) {
                $dirs[] = dirname($_SERVER['DOCUMENT_ROOT']);
            }
        }
        foreach ($dirs as $d) {
            if ($d && is_file($d . '/vendor/autoload.php')) {
                return $d . '/vendor/autoload.php';
            }
        }
        return null;
    }

    private static function guard(callable $fn)
    {
        if (self::$inside) {
            return null; // a hook that triggered another hook
        }
        self::$inside = true;
        try {
            return $fn();
        } catch (\Throwable $e) {
            return null;
        } finally {
            self::$inside = false;
        }
    }

    private static function tryHook()
    {
        self::guard(static function () {
            if (!class_exists('Illuminate\\Container\\Container', false)) {
                return;
            }
            $app = \Illuminate\Container\Container::getInstance();
            if (!($app instanceof \Illuminate\Contracts\Foundation\Application)) {
                return;
            }
            // The autoloader stays registered (a flag check from now on):
            // removing it while PHP is inside an autoload call would skip
            // the loaders after it — Composer's — for this very class.
            self::$hooked = true;
            if (method_exists($app, 'basePath')) {
                self::$base = $app->basePath();
            }
            $app->booted(static function ($app) {
                self::guard(static function () use ($app) {
                    self::register($app);
                });
            });
        });
    }

    private static function register($app)
    {
        $cfg = self::$cfg;
        if (!empty($cfg['dumps'])) {
            self::installDumper();
        }
        if (empty($cfg['deep']) || !isset($app['events'])) {
            return;
        }
        $ev = $app['events'];
        $on = static function ($name, callable $fn) use ($ev) {
            $ev->listen($name, static function (...$args) use ($fn) {
                self::guard(static function () use ($fn, $args) {
                    $fn(...$args);
                });
            });
        };

        $on('Illuminate\\Database\\Events\\QueryExecuted', static function ($e) {
            $src = self::source();
            self::add('query', [
                'sql' => self::str($e->sql, 10000),
                'bindings' => self::redactBindings((string) $e->sql, self::values((array) $e->bindings)),
                'ms' => round((float) $e->time, 2),
                'conn' => (string) ($e->connectionName ?? ''),
                'file' => $src[0],
                'line' => $src[1],
            ]);
        });

        // Cache
        $cache = static function ($op) {
            return static function ($e) use ($op) {
                $d = ['op' => $op, 'key' => self::str($e->key ?? '', 300)];
                if (property_exists($e, 'storeName') && $e->storeName) {
                    $d['store'] = (string) $e->storeName;
                }
                if ($op === 'write' && property_exists($e, 'seconds')) {
                    $d['ttl'] = $e->seconds;
                }
                if (!empty($e->tags)) {
                    $d['tags'] = array_values(array_map('strval', (array) $e->tags));
                }
                self::add('cache', $d);
            };
        };
        $on('Illuminate\\Cache\\Events\\CacheHit', $cache('hit'));
        $on('Illuminate\\Cache\\Events\\CacheMissed', $cache('miss'));
        $on('Illuminate\\Cache\\Events\\KeyWritten', $cache('write'));
        $on('Illuminate\\Cache\\Events\\KeyForgotten', $cache('forget'));

        // Jobs: dispatched from a request, and run by a worker (each job
        // is its own timeline in a worker).
        $on('Illuminate\\Queue\\Events\\JobQueued', static function ($e) {
            $name = is_object($e->job) ? get_class($e->job) : (is_string($e->job) ? $e->job : 'Closure');
            self::add('job', ['op' => 'queued', 'name' => $name, 'conn' => (string) $e->connectionName,
                'queue' => property_exists($e, 'queue') ? (string) $e->queue : '', 'id' => (string) ($e->id ?? '')]);
        });
        $on('Illuminate\\Queue\\Events\\JobProcessing', static function ($e) {
            self::flush();
            $id = method_exists($e->job, 'uuid') ? (string) $e->job->uuid() : '';
            self::$rid = 'job-' . ($id !== '' ? $id : bin2hex(random_bytes(6)));
            self::$jobStart = microtime(true);
            self::$count = 0;
            self::add('job', ['op' => 'processing', 'name' => self::jobName($e->job), 'conn' => (string) $e->connectionName,
                'queue' => (string) $e->job->getQueue(), 'attempts' => (int) $e->job->attempts(), 'id' => $id]);
        });
        $jobDone = static function ($op) {
            return static function ($e) use ($op) {
                $d = ['op' => $op, 'name' => self::jobName($e->job), 'conn' => (string) $e->connectionName,
                    'queue' => (string) $e->job->getQueue(), 'ms' => round((microtime(true) - self::$jobStart) * 1000, 2),
                    'id' => method_exists($e->job, 'uuid') ? (string) $e->job->uuid() : ''];
                if ($op === 'failed' && isset($e->exception)) {
                    $d['error'] = get_class($e->exception) . ': ' . self::str($e->exception->getMessage(), 500);
                }
                self::add('job', $d);
                self::flush();
                self::$rid = self::$baseRid;
            };
        };
        $on('Illuminate\\Queue\\Events\\JobProcessed', $jobDone('processed'));
        $on('Illuminate\\Queue\\Events\\JobFailed', $jobDone('failed'));

        // HTTP client
        $on('Illuminate\\Http\\Client\\Events\\RequestSending', static function ($e) {
            self::$httpStart[$e->request->method() . ' ' . $e->request->url()][] = microtime(true);
        });
        $httpEnd = static function ($e, $status, $error) {
            $k = $e->request->method() . ' ' . $e->request->url();
            $t0 = isset(self::$httpStart[$k]) ? array_shift(self::$httpStart[$k]) : null;
            $ms = $t0 ? round((microtime(true) - $t0) * 1000, 2) : null;
            if ($status !== null && method_exists($e->response, 'handlerStats')) {
                $st = $e->response->handlerStats();
                if (isset($st['total_time'])) {
                    $ms = round($st['total_time'] * 1000, 2);
                }
            }
            $d = ['method' => $e->request->method(), 'url' => self::str($e->request->url(), 1000), 'status' => $status, 'ms' => $ms,
                'headers' => self::redactHeaders((array) $e->request->headers())];
            if ($error) {
                $d['error'] = $error;
            }
            self::add('http', $d);
        };
        $on('Illuminate\\Http\\Client\\Events\\ResponseReceived', static function ($e) use ($httpEnd) {
            $httpEnd($e, $e->response->status(), null);
        });
        $on('Illuminate\\Http\\Client\\Events\\ConnectionFailed', static function ($e) use ($httpEnd) {
            $httpEnd($e, null, isset($e->exception) ? self::str($e->exception->getMessage(), 500) : 'connection failed');
        });

        // Views
        $on('composing: *', static function ($name, $data = []) {
            $view = is_array($data) && isset($data[0]) ? $data[0] : null;
            if (!is_object($view) || !method_exists($view, 'getName')) {
                return;
            }
            $vn = (string) $view->getName();
            if (strncmp($vn, 'laravel-exceptions', 18) === 0) {
                return; // Laravel's own error page
            }
            self::add('view', ['name' => $vn, 'file' => self::rel(method_exists($view, 'getPath') ? (string) $view->getPath() : '')]);
        });

        // Logs and reported exceptions (the Logs tab tails the files; these
        // place them on the request's timeline).
        $on('Illuminate\\Log\\Events\\MessageLogged', static function ($e) {
            $ctx = is_array($e->context) ? $e->context : [];
            if (isset($ctx['exception']) && $ctx['exception'] instanceof \Throwable) {
                self::exception($ctx['exception']);
                return;
            }
            self::add('log', ['level' => (string) $e->level, 'message' => self::str((string) $e->message, 2000)]);
        });

        $on('Illuminate\\Mail\\Events\\MessageSent', static function ($e) {
            $d = [];
            $msg = $e->message ?? null;
            if (is_object($msg) && method_exists($msg, 'getSubject')) {
                $d['subject'] = (string) $msg->getSubject();
                $d['to'] = self::addresses(method_exists($msg, 'getTo') ? $msg->getTo() : []);
                $d['from'] = self::addresses(method_exists($msg, 'getFrom') ? $msg->getFrom() : []);
            }
            if (isset($e->sent) && is_object($e->sent) && method_exists($e->sent, 'getMessageId')) {
                $d['messageId'] = (string) $e->sent->getMessageId();
            }
            self::add('mail', $d);
        });

        $on('Illuminate\\Foundation\\Http\\Events\\RequestHandled', static function ($e) {
            self::$status = method_exists($e->response, 'getStatusCode') ? $e->response->getStatusCode() : null;
            $route = method_exists($e->request, 'route') ? $e->request->route() : null;
            if (is_object($route)) {
                self::$route = [
                    'name' => method_exists($route, 'getName') ? $route->getName() : null,
                    'action' => method_exists($route, 'getActionName') ? $route->getActionName() : null,
                    'uri' => method_exists($route, 'uri') ? $route->uri() : null,
                ];
            }
        });

        // The app's own events (framework noise left out).
        $ev->listen('*', static function ($name, $payload = []) {
            if (!is_string($name) || self::frameworkEvent($name)) {
                return;
            }
            self::guard(static function () use ($name) {
                self::add('event', ['name' => self::str($name, 300)]);
            });
        });
    }

    private static function frameworkEvent($name)
    {
        static $prefixes = ['Illuminate\\', 'Laravel\\', 'Symfony\\', 'eloquent.', 'composing: ', 'creating: ',
            'bootstrapping: ', 'bootstrapped: ', 'kernel.', 'Livewire\\Features\\', 'Inertia\\'];
        foreach ($prefixes as $p) {
            if (strncmp($name, $p, strlen($p)) === 0) {
                return true;
            }
        }
        return false;
    }

    private static function jobName($job)
    {
        try {
            if (method_exists($job, 'resolveName')) {
                return (string) $job->resolveName();
            }
            return method_exists($job, 'getName') ? (string) $job->getName() : get_class($job);
        } catch (\Throwable $e) {
            return 'job';
        }
    }

    private static function addresses($list)
    {
        $out = [];
        foreach ((array) $list as $a) {
            $out[] = is_object($a) && method_exists($a, 'getAddress') ? $a->getAddress() : (string) $a;
        }
        return $out;
    }

    // ── dumps ─────────────────────────────────────────────────────────
    private static function installDumper()
    {
        $prev = \Symfony\Component\VarDumper\VarDumper::setHandler(static function ($var, $label = null) {
            self::dump($var, $label);
        });
        if (self::$prevDumper === null && $prev !== null) {
            self::$prevDumper = $prev;
        }
    }

    private static function dump($var, $label)
    {
        self::guard(static function () use ($var, $label) {
            $cloner = new \Symfony\Component\VarDumper\Cloner\VarCloner();
            $dumper = new \Symfony\Component\VarDumper\Dumper\CliDumper();
            $dumper->setColors(false);
            $text = (string) $dumper->dump($cloner->cloneVar($var), true);
            $src = self::source();
            $d = ['text' => self::str(rtrim($text), 65536), 'file' => $src[0], 'line' => $src[1]];
            if ($label !== null && $label !== '') {
                $d['label'] = (string) $label;
            }
            self::add('dump', $d);
            if (self::$cli) {
                self::flush(); // a worker may never reach shutdown
            }
        });
        if (!empty(self::$cfg['dumpsInPage'])) {
            try {
                if (self::$prevDumper) {
                    (self::$prevDumper)($var, $label);
                } else {
                    $cloner = new \Symfony\Component\VarDumper\Cloner\VarCloner();
                    $dumper = self::$cli ? new \Symfony\Component\VarDumper\Dumper\CliDumper() : new \Symfony\Component\VarDumper\Dumper\HtmlDumper();
                    $dumper->dump($cloner->cloneVar($var));
                }
            } catch (\Throwable $e) {
            }
        }
    }

    // ── recording ─────────────────────────────────────────────────────
    private static function exception(\Throwable $ex)
    {
        $trace = [];
        foreach (array_slice($ex->getTrace(), 0, 40) as $f) {
            $trace[] = [
                'file' => isset($f['file']) ? self::rel($f['file']) : '',
                'line' => $f['line'] ?? 0,
                'call' => (isset($f['class']) ? $f['class'] . ($f['type'] ?? '::') : '') . ($f['function'] ?? ''),
            ];
        }
        self::add('exception', ['class' => get_class($ex), 'message' => self::str($ex->getMessage(), 2000),
            'file' => self::rel($ex->getFile()), 'line' => $ex->getLine(), 'trace' => $trace]);
    }

    private static function add($type, array $data)
    {
        if (++self::$count > self::MAX_EVENTS) {
            self::$dropped++;
            return;
        }
        $data = ['type' => $type, 't' => round(microtime(true), 4), 'rid' => self::$rid] + $data;
        self::$buf[] = $data;
        if (count(self::$buf) >= 200) {
            self::flush();
        }
    }

    public static function shutdown()
    {
        self::guard(static function () {
            $ms = round((microtime(true) - self::$start) * 1000, 2);
            if (self::$cli) {
                $argv = $_SERVER['argv'] ?? [];
                self::$rid = self::$baseRid;
                self::$count = 0;
                self::add('command', ['command' => self::str(implode(' ', array_slice($argv, 1)), 500), 'ms' => $ms,
                    'memory' => memory_get_peak_usage(true)]);
            } else {
                $err = error_get_last();
                $d = ['method' => $_SERVER['REQUEST_METHOD'] ?? 'GET', 'uri' => self::str($_SERVER['REQUEST_URI'] ?? '/', 2000),
                    'status' => self::$status ?? (http_response_code() ?: 200), 'ms' => $ms, 'memory' => memory_get_peak_usage(true)];
                if (self::$route) {
                    $d['route'] = self::$route;
                }
                if ($err && in_array($err['type'], [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR], true)) {
                    $d['fatal'] = self::str($err['message'], 1000) . ' in ' . self::rel($err['file']) . ':' . $err['line'];
                    if ($d['status'] < 500) {
                        $d['status'] = 500;
                    }
                }
                self::$count = 0;
                self::add('request', $d);
            }
            if (self::$dropped) {
                self::$count = 0;
                self::add('dropped', ['count' => self::$dropped]);
                self::$dropped = 0;
            }
        });
        self::flush();
    }

    public static function flush()
    {
        if (!self::$buf) {
            return;
        }
        $lines = '';
        foreach (self::$buf as $e) {
            $j = json_encode($e, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE | JSON_PARTIAL_OUTPUT_ON_ERROR);
            if (is_string($j)) {
                $lines .= $j . "\n";
            }
        }
        self::$buf = [];
        $file = self::$dir . '/events.jsonl';
        $lock = @fopen(self::$dir . '/events.lock', 'c');
        if ($lock) {
            @flock($lock, LOCK_EX);
        }
        try {
            clearstatcache(true, $file);
            if (@filesize($file) > self::CAP) {
                @rename($file, self::$dir . '/events.1.jsonl');
            }
            @file_put_contents($file, $lines, FILE_APPEND);
        } finally {
            if ($lock) {
                @flock($lock, LOCK_UN);
                @fclose($lock);
            }
        }
    }

    // ── helpers ───────────────────────────────────────────────────────
    // source is the first stack frame in the app's own code.
    private static function source()
    {
        $vendor = DIRECTORY_SEPARATOR . 'vendor' . DIRECTORY_SEPARATOR;
        foreach (debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS, 60) as $f) {
            if (empty($f['file']) || $f['file'] === __FILE__ || strpos($f['file'], $vendor) !== false) {
                continue;
            }
            if (strpos($f['file'], 'mullion-watch') !== false) {
                continue;
            }
            return [self::rel($f['file']), $f['line'] ?? 0];
        }
        return ['', 0];
    }

    private static function rel($path)
    {
        $path = (string) $path;
        if (self::$base !== '' && strncmp($path, self::$base . DIRECTORY_SEPARATOR, strlen(self::$base) + 1) === 0) {
            return substr($path, strlen(self::$base) + 1);
        }
        return $path;
    }

    private static function str($s, $max = self::MAX_STR)
    {
        $s = (string) $s;
        return strlen($s) > $max ? substr($s, 0, $max) . '…' : $s;
    }

    private static function values(array $bindings)
    {
        $out = [];
        foreach ($bindings as $b) {
            if ($b === null || is_bool($b) || is_int($b) || is_float($b)) {
                $out[] = $b;
            } elseif (is_string($b)) {
                $out[] = preg_match('//u', $b) ? self::str($b, 500) : '<binary ' . strlen($b) . ' bytes>';
            } elseif ($b instanceof \DateTimeInterface) {
                $out[] = $b->format('Y-m-d H:i:s');
            } elseif (is_object($b) && method_exists($b, '__toString')) {
                $out[] = self::str((string) $b, 500);
            } elseif ($b instanceof \UnitEnum) {
                $out[] = $b instanceof \BackedEnum ? $b->value : $b->name;
            } else {
                $out[] = is_object($b) ? get_class($b) : gettype($b);
            }
        }
        return $out;
    }

    const SECRET = '/pass(word|wd|phrase)?|secret|token|api[_-]?key|authori[sz]ation|cookie|credential|private[_-]?key|otp|pin_code|cvv|card_number/i';

    private static function redactHeaders(array $headers)
    {
        $out = [];
        foreach ($headers as $k => $v) {
            $out[$k] = preg_match(self::SECRET, (string) $k) ? '[redacted]' : $v;
        }
        return $out;
    }

    // redactBindings blanks the values bound to secret-looking columns
    // (`password` = ?, insert (…, password, …) values (…, ?, …)). The
    // Go side applies the same rule again before showing anything.
    private static function redactBindings($sql, array $bindings)
    {
        if (!$bindings || !preg_match(self::SECRET, $sql)) {
            return $bindings;
        }
        $cols = self::placeholderColumns($sql);
        foreach ($bindings as $i => $v) {
            if (isset($cols[$i]) && preg_match(self::SECRET, $cols[$i])) {
                $bindings[$i] = '[redacted]';
            }
        }
        return $bindings;
    }

    private static function placeholderColumns($sql)
    {
        $cols = [];
        $insert = null;
        if (preg_match('/^\s*(insert|replace)\b.*?\(([^)]*)\)\s*values\s*\(/is', $sql, $m)) {
            $insert = array_map(static function ($c) {
                return trim($c, " \t\n\r`\"[]");
            }, explode(',', $m[2]));
        }
        $n = strlen($sql);
        $q = null;
        $idx = 0;
        $valuesAt = $insert !== null ? stripos($sql, 'values') : false;
        for ($i = 0; $i < $n; $i++) {
            $c = $sql[$i];
            if ($q !== null) {
                if ($c === $q) {
                    $q = null;
                }
                continue;
            }
            if ($c === "'" || $c === '"' || $c === '`') {
                $q = $c;
                continue;
            }
            if ($c !== '?') {
                continue;
            }
            if ($insert !== null && $valuesAt !== false && $i > $valuesAt) {
                $cols[] = $insert[$idx % max(1, count($insert))] ?? '';
                $idx++;
                continue;
            }
            $before = substr($sql, max(0, $i - 80), $i - max(0, $i - 80));
            $cols[] = preg_match('/([A-Za-z_][\w]*)[`"\]]?\s*(=|<>|!=|<=|>=|<|>|\blike\b|\bin\s*\([^)]*)\s*$/i', $before, $mm) ? $mm[1] : '';
        }
        return $cols;
    }
}
